-- Live Triptych achievement rewards (server-authored 950xxxx/960xxxx set).
-- Policy (2026-10-16, halved): alternate advancement plus platinum-scale coin, banded
-- by achievement points:
--   AA   = max(1, points / 10)
--   coin = points / 2 platinum (reward_type 3 stores copper, so amount = points * 500)
-- Titles and a bag item are reserved for the two Original meta achievements.
-- Automatic rewards deliver on completion and are reconciled on login, so applying this
-- file also grants them to characters that already completed these rows.

SET NAMES utf8mb4;
START TRANSACTION;

ON DUPLICATE KEY UPDATE prefix = VALUES(prefix), suffix = VALUES(suffix);

ON DUPLICATE KEY UPDATE reward_type=VALUES(reward_type), reward_data_id=VALUES(reward_data_id), amount=VALUES(amount), description=VALUES(description), enabled=VALUES(enabled);

ON DUPLICATE KEY UPDATE reward_id=VALUES(reward_id);

COMMIT;
